#include <stdio.h>
#include <stdlib.h>
#include <string.h>

char* reverseWords(char* s) {

    // Spaces in the beggining
    while(*s == ' ')  s = s + 1;
    // Spaces in the end
    while(s[strlen(s)-1] == ' ') s[strlen(s)-1] = '\0';

    // Remove any extra spaces among words 
    int index = 0;
    int space = 0;
    for(int i = 0; i < strlen(s); i++) {

        if(space == 1 && s[i] == ' ')
            continue;
        else
            space = 0;

        if(s[i] == ' ' && space == 0)
            space = 1;
        
        s[index] = s[i];
        index++;
    }
    s[index] = '\0';
    
    // Reverse the entire string.
    int left = 0;
    int right = strlen(s) - 1;
    char temp;
    while(left <= right) {
        temp = s[left];
        s[left] = s[right];
        s[right] = temp;
        right--;
        left++;
    }

    int start = 0;
    int end = start;
    while(start <= strlen(s)-1)
    {
        while(s[end] != ' ' && s[end] != '\0') 
            end++;

        left = start;
        right = end - 1;
        while(left <= right) {
            temp = s[left];
            s[left] = s[right];
            s[right] = temp;
            right--;
            left++;
        }
        start = end + 1;
        end = start;
    }

    return s;
}
  

